  /**
   * @method
   * @name grvt#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://api-docs.grvt.io/market_data_api/#orderbook-levels
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.loc] crypto location, default: us
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{
                            {std::string("instrument"), this->marketId(symbol)},
                        };
                        if (isTrue(isEqual(limit, ccxt::any{}))) {
                          limit = 100;
                        }
                        if (isTrue(isLessThanOrEqual(limit, 500))) {
                          ::setValue(request, std::string("depth"),
                                     this->findNearestCeiling(
                                         ccxt::list{10, 50, 100, 500}, limit));
                        }
                        ccxt::any response =
                            awaitValue(this->publicMarketPostFullV1Book(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "result": {
                        //            "event_time": "1764777396650000000",
                        //            "instrument": "BTC_USDT_Perp",
                        //            "bids": [
                        //                { "price": "92336.0", "size": "0.005",
                        //                "num_orders": "1" },
                        //                ...
                        //            ],
                        //            "asks": [
                        //                { "price": "92336.1", "size": "5.711",
                        //                "num_orders": "37" },
                        //                ...
                        //            ]
                        //        }
                        //    }
                        //
                        ccxt::any result = this->safeDict(
                            response, std::string("result"), ccxt::dict{});
                        ccxt::any timestamp = this->parse8601(this->safeString(
                            result, std::string("event_time")));
                        ccxt::any marketId =
                            this->safeString(result, std::string("instrument"));
                        return this->parseOrderBook(
                            result, this->safeSymbol(marketId), timestamp,
                            std::string("bids"), std::string("asks"),
                            std::string("price"), std::string("size"));
                      })
        .share();
  }

  /**
   * @method
   * @name grvt#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://api-docs.grvt.io/market_data_api/#trade_1
   * @param {string} symbol unified symbol of the market
   * @param {int} [since] timestamp in ms of the earliest item to fetch
   * @param {int} [limit] the maximum amount of items to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is the current time
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 ccxt::any requestparamsVariable =
                     this->handleUntilOptionString(std::string("end_time"),
                                                   request, params, 1000000);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_time"),
                              this->numberToString(multiply(since, 1000000)));
                 }
                 ccxt::any response =
                     awaitValue(this->publicMarketPostFullV1TradeHistory(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "next":
                 //        "eyJ0cmFkZUlkIjo2NDc5MTAyMywidHJhZGVJbmRleCI6MX0",
                 //        "result": [
                 //            {
                 //                "event_time": "1764779531332118705",
                 //                "instrument": "ETH_USDT_Perp",
                 //                "is_taker_buyer": false,
                 //                "size": "23.73",
                 //                "price": "3089.88",
                 //                "mark_price": "3089.360002315",
                 //                "index_price": "3090.443723246",
                 //                "interest_rate": "0.0",
                 //                "forward_price": "0.0",
                 //                "trade_id": "64796657-1",
                 //                "venue": "ORDERBOOK",
                 //                "is_rpi": false
                 //            },
                 //            ...
                 //
                 ccxt::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseTrades(result, market, since, limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //
    //            {
    //                "event_time": "1764779531332118705",
    //                "instrument": "ETH_USDT_Perp",
    //                "size": "23.73",
    //                "price": "3089.88",
    //                "is_rpi": false,
    //                "mark_price": "3089.360002315",
    //                "index_price": "3090.443723246",
    //                "interest_rate": "0.0",
    //                "forward_price": "0.0",
    //                "trade_id": "64796657-1",
    //                "venue": "ORDERBOOK",
    //                "is_taker_buyer": false
    //            }
    //
    // fetchMyTrades
    //
    //            {
    //                "event_time": "1764945709702747558",
    //                "instrument": "BTC_USDT_Perp",
    //                "size": "0.001",
    //                "price": "90000.0",
    //                "is_rpi": false
    //                "mark_price": "90050.164063298",
    //                "index_price": "90089.803654938",
    //                "interest_rate": "0.0",
    //                "forward_price": "0.0",
    //                "trade_id": "65424692-2",
    //                "venue": "ORDERBOOK",
    //                "is_buyer": true,
    //                "is_taker": false,
    //                "broker": "UNSPECIFIED",
    //                "realized_pnl": "0.0",
    //                "fee": "-0.00009",
    //                "fee_rate": "0.0",
    //                "order_id": "0x01010105034cddc7000000006621285c",
    //                "client_order_id": "1375879248",
    //                "signer": "0x42c9f56f2c9da534f64b8806d64813b29c62a01d",
    //                "sub_account_id": "2147050003876484",
    //            }
    //
    ccxt::any marketId = this->safeString(trade, std::string("instrument"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp =
        this->safeIntegerProduct(trade, std::string("event_time"), 0.000001);
    ccxt::any takerOrMaker = ccxt::any{};
    ccxt::any isTakerBuyer =
        this->safeBool(trade, std::string("is_taker_buyer"));
    ccxt::any side = ccxt::any{};
    if (isTrue(!isEqual(isTakerBuyer, ccxt::any{}))) {
      side = (isTrue(isTakerBuyer) ? ccxt::any(std::string("buy"))
                                   : ccxt::any(std::string("sell")));
      takerOrMaker = std::string("taker");
    } else {
      ccxt::any isTaker =
          (isEqual(this->safeBool(trade, std::string("is_taker")), true));
      ccxt::any isBuyer =
          (isEqual(this->safeBool(trade, std::string("is_buyer")), true));
      takerOrMaker = (isTrue(isTaker) ? ccxt::any(std::string("taker"))
                                      : ccxt::any(std::string("maker")));
      side = (isTrue(isBuyer) ? ccxt::any(std::string("buy"))
                              : ccxt::any(std::string("sell")));
    }
    ccxt::any fee = ccxt::any{};
    ccxt::any feeString = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeString, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), this->parseNumber(feeString)},
          {std::string("currency"), ::getValue(market, std::string("quote"))},
          {std::string("rate"),
           this->safeNumber(trade, std::string("fee_rate"))},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"),
             this->safeString(trade, std::string("trade_id"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("side"), side},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"),
             this->safeString(trade, std::string("price"))},
            {std::string("amount"),
             this->safeString(trade, std::string("size"))},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
            {std::string("order"),
             this->safeString(trade, std::string("order_id"))},
        },
        market);
  }

  /**
   * @method
   * @name grvt#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://api-docs.grvt.io/market_data_api/#candlestick_1
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest item to fetch
   * @param {int} [limit] the maximum amount of items to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms for the ending date filter,
   * default is the current time
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any maxLimit = 1000;
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("paginate"),
                     false);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, maxLimit));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 ccxt::any priceTypeMap = ccxt::dict{
                     {std::string("last"), std::string("TRADE")},
                     {std::string("mark"), std::string("MARK")},
                     {std::string("index"), std::string("INDEX")},
                 };
                 ccxt::any selectedPriceType = this->safeString(
                     params, std::string("priceType"), std::string("last"));
                 ::setValue(request, std::string("type"),
                            this->safeString(priceTypeMap, selectedPriceType));
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 ccxt::any requestparamsVariable =
                     this->handleUntilOptionString(std::string("end_time"),
                                                   request, params, 1000000);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_time"),
                              this->numberToString(multiply(since, 1000000)));
                 }
                 ccxt::any response =
                     awaitValue(this->publicMarketPostFullV1Kline(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "result": [
                 //            {
                 //                "open_time": "1767288240000000000",
                 //                "close_time": "1767288300000000000",
                 //                "open": "88178.8",
                 //                "close": "88176.7",
                 //                "high": "88192.7",
                 //                "low": "88176.6",
                 //                "volume_b": "15.32",
                 //                "volume_q": "1350962.4782",
                 //                "trades": 38,
                 //                "instrument": "BTC_USDT_Perp"
                 //            },
                 //        ],
                 //        "next": "eyJvcGVuVGltZSI6MTc2NzI1ODMwMDAwMDAwMDAwMH0"
                 //    }
                 //
                 ccxt::any candles = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseOHLCVs(candles, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //            {
    //                "open_time": "1767288240000000000",
    //                "close_time": "1767288300000000000",
    //                "open": "88178.8",
    //                "close": "88176.7",
    //                "high": "88192.7",
    //                "low": "88176.6",
    //                "volume_b": "15.32",
    //                "volume_q": "1350962.4782",
    //                "trades": 38,
    //                "instrument": "BTC_USDT_Perp"
    //            }
    //
    return ccxt::list{
        this->safeIntegerProduct(ohlcv, std::string("open_time"), 0.000001),
        this->safeNumber(ohlcv, std::string("open")),
        this->safeNumber(ohlcv, std::string("high")),
        this->safeNumber(ohlcv, std::string("low")),
        this->safeNumber(ohlcv, std::string("close")),
        this->safeNumber(ohlcv, std::string("volume_b"))};
  }

  /**
   * @method
   * @name grvt#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see https://api-docs.grvt.io/market_data_api/#funding-rate
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest item
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingRateHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchFundingRateHistory"), symbol, since,
                       limit, std::string("8h"), params));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("instrument"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 ccxt::any requestparamsVariable =
                     this->handleUntilOptionString(std::string("end_time"),
                                                   request, params, 1000000);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_time"),
                              this->numberToString(multiply(since, 1000000)));
                 }
                 ccxt::any response =
                     awaitValue(this->publicMarketPostFullV1Funding(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "result": [
                 //            {
                 //                "instrument": "BTC_USDT_Perp",
                 //                "funding_rate": "-0.0034",
                 //                "funding_time": "1760494260000000000",
                 //                "mark_price": "112721.159060304",
                 //                "funding_rate_8_h_avg": "-0.0038",
                 //                "funding_interval_hours": "0"
                 //            },
                 //            ...
                 //        ],
                 //        "next":
                 //        "eyJmdW5kaW5nVGltZSI6MTc2MDQ5NDI2MDAwMDAwMDAwMH0"
                 //    }
                 //
                 ccxt::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 return this->parseFundingRateHistories(result, market);
               })
        .share();
  }

  ccxt::any parseFundingRateHistory(ccxt::any rawItem,
                                    ccxt::any market = ccxt::any{}) override {
    //
    //            {
    //                "instrument": "BTC_USDT_Perp",
    //                "funding_rate": "-0.0034",
    //                "funding_time": "1760494260000000000",
    //                "mark_price": "112721.159060304",
    //                "funding_rate_8_h_avg": "-0.0038",
    //                "funding_interval_hours": "0"
    //            },
    //
    ccxt::any marketId = this->safeString(rawItem, std::string("instrument"));
    ccxt::any ts = this->safeIntegerProduct(
        rawItem, std::string("funding_time"), 0.000001);
    // the api documents funding_rate in percentage points, and a unified
    // fundingRate is a fraction, with the Manual's examples reading 0.000072
    ccxt::any rate = this->safeString(rawItem, std::string("funding_rate"));
    return ccxt::dict{
        {std::string("info"), rawItem},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("fundingRate"),
         this->parseNumber(ccxt::Precise::stringDiv(rate, std::string("100")))},
        {std::string("timestamp"), ts},
        {std::string("datetime"), this->iso8601(ts)},
    };
  }

  virtual ccxt::any getSubAccountId(ccxt::any params) {
    ccxt::any subAccountId = ccxt::any{};
    ccxt::any subAccountIdparamsVariable = this->handleOptionAndParams(
        params, std::string("getSubAccountId"), std::string("accountId"));
    subAccountId = ::getValue(subAccountIdparamsVariable, 0);
    params = ::getValue(subAccountIdparamsVariable, 1);
    if (isTrue(isEqual(subAccountId, ccxt::any{}))) {
      throw ArgumentsRequired(toString(
          add(this->id,
              std::string(
                  " you should set \"accountId\" in options or params, which "
                  "can be found in the grvt dashboard, under Api-Keys page"))));
    }
    return toString(subAccountId);
  }

